{
  "question": "Given an array of integers `nums` and an integer `k`, return the total number of continuous subarrays whose sum equals `k` using a hash table to store prefix sum frequencies.",
  "function_name": "subarray_sum",
  "signature": "def subarray_sum(nums: list[int], k: int) -> int",
  "checker": "exact",
  "reference_solution": "def subarray_sum(nums: list[int], k: int) -> int:\n    from collections import defaultdict\n    count = 0\n    current_sum = 0\n    prefix_sums = defaultdict(int)\n    prefix_sums[0] = 1\n    for num in nums:\n        current_sum += num\n        count += prefix_sums[current_sum - k]\n        prefix_sums[current_sum] += 1\n    return count",
  "cases": [
    {
