      "args_json": "[[1, 2, 3], 3]",
      "expected_json": "2",
      "note": "Subarrays [1, 2] and [3] sum to 3."
    },
    {
      "args_json": "[[1, -1, 1], 0]",
      "expected_json": "1",
      "note": "Subarray [1, -1] sums to 0."
    },
    {
